pub unsafe fn reset_state() {
    P_HSD_GObj = core::mem::zeroed();
    P_HSD_JObj = core::mem::zeroed();
    P_HSD_DObj = core::mem::zeroed();
    P_HSD_MObj = core::mem::zeroed();
    P_HSD_TObj = core::mem::zeroed();
    P_HSD_Material = core::mem::zeroed();
    P_HSD_AObj = core::mem::zeroed();
    P_HSD_MatAnimJoint = core::mem::zeroed();
    P_HSD_MatAnim = core::mem::zeroed();
    P_DynamicModelDesc = core::mem::zeroed();
    P_VsSceneController = core::mem::zeroed();
    P_HSD_Archive = core::mem::zeroed();
    m::ifStatus_HudInfo = core::mem::zeroed();
    m::ifStatus_804D6D60 = core::mem::zeroed();
    m::ifStatus_804D6D61 = core::mem::zeroed();
    super::MAJP = core::mem::zeroed();
    super::NMOD = core::mem::zeroed();
    super::ARCP = core::mem::zeroed();
    super::V3A = core::mem::zeroed();
    super::GCOL = core::mem::zeroed();
    super::GOP = core::mem::zeroed();
    super::CHR = core::mem::zeroed();
    m::ext::HSD_GObj_JObjKind = core::mem::zeroed();
    for i in 0..6usize { fill_HSD_GObj(&mut P_HSD_GObj[i]); }
    for i in 0..10usize { fill_HSD_JObj(&mut P_HSD_JObj[i]); }
    for i in 0..4usize { fill_HSD_DObj(&mut P_HSD_DObj[i]); }
    for i in 0..4usize { fill_HSD_MObj(&mut P_HSD_MObj[i]); }
    for i in 0..4usize { fill_HSD_TObj(&mut P_HSD_TObj[i]); }
    for i in 0..4usize { fill_HSD_Material(&mut P_HSD_Material[i]); }
    for i in 0..3usize { fill_HSD_AObj(&mut P_HSD_AObj[i]); }
    for i in 0..6usize { fill_HSD_MatAnimJoint(&mut P_HSD_MatAnimJoint[i]); }
    for i in 0..2usize { fill_HSD_MatAnim(&mut P_HSD_MatAnim[i]); }
    for i in 0..2usize { fill_DynamicModelDesc(&mut P_DynamicModelDesc[i]); }
    for i in 0..1usize { fill_VsSceneController(&mut P_VsSceneController[i]); }
    for i in 0..1usize { fill_HSD_Archive(&mut P_HSD_Archive[i]); }
    fill_HudIndex(&mut m::ifStatus_HudInfo);
    m::ifStatus_804D6D60 = ((0 + (rnd() % 8) as i32)) as _;
    m::ifStatus_804D6D61 = ((0 + (rnd() % 2) as i32)) as _;
    for i in 0..2usize { super::MAJP[i] = (pick_HSD_MatAnimJoint(0)) as _; }
    for i in 0..2usize { super::NMOD[i] = (pick_DynamicModelDesc(0)) as _; }
    super::ARCP = (pick_HSD_Archive(0)) as _;
    fill_Vec3(&mut super::V3A);
    for i in 0..3usize { fill_GXColor(&mut super::GCOL[i]); }
    for i in 0..1usize { super::GOP[i] = (0) as _; }
    for i in 0..1usize { super::CHR[i] = (fv()) as _; }
    m::ext::HSD_GObj_JObjKind = (20) as _;
}
pub unsafe fn hash_state() {
    for i in 0..6usize { hash_HSD_GObj(&P_HSD_GObj[i]); }
    for i in 0..10usize { hash_HSD_JObj(&P_HSD_JObj[i]); }
    for i in 0..4usize { hash_HSD_DObj(&P_HSD_DObj[i]); }
    for i in 0..4usize { hash_HSD_MObj(&P_HSD_MObj[i]); }
    for i in 0..4usize { hash_HSD_TObj(&P_HSD_TObj[i]); }
    for i in 0..4usize { hash_HSD_Material(&P_HSD_Material[i]); }
    for i in 0..3usize { hash_HSD_AObj(&P_HSD_AObj[i]); }
    for i in 0..6usize { hash_HSD_MatAnimJoint(&P_HSD_MatAnimJoint[i]); }
    for i in 0..2usize { hash_HSD_MatAnim(&P_HSD_MatAnim[i]); }
    for i in 0..2usize { hash_DynamicModelDesc(&P_DynamicModelDesc[i]); }
    for i in 0..1usize { hash_VsSceneController(&P_VsSceneController[i]); }
    for i in 0..1usize { hash_HSD_Archive(&P_HSD_Archive[i]); }
    hash_HudIndex(&m::ifStatus_HudInfo);
    for i in 0..4usize { hm(m::ifStatus_804D57A8[i] as u32); }
    for i in 0..4usize { hm(m::ifStatus_804D57AC[i] as u32); }
    hm(m::ifStatus_804D6D60 as u32);
    hm(m::ifStatus_804D6D61 as u32);
    for i in 0..2usize { hm(pi(super::MAJP[i])); }
    for i in 0..2usize { hm(pi(super::NMOD[i])); }
    hm(pi(super::ARCP));
    hash_Vec3(&super::V3A);
    for i in 0..3usize { hash_GXColor(&super::GCOL[i]); }
    for i in 0..1usize { hm(pi(super::GOP[i])); }
    for i in 0..1usize { hm(super::CHR[i] as u32); }
    hm(m::ext::HSD_GObj_JObjKind as u32);
}
